INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62260806', 62260806, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN TINGGI AGAMA MAKASSAR 01', 'KEBUTUHAN SEHARI HARI PERKANTORAN', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 465764000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Layanan', 'Pengadaan Satpam [4 Org x 13 Bln]; dan Petugas kebersihan [4 org x 13 bln].', 'Spesefikasi: Pendidikan: minimal SMA/SMK sederajat. Kesehatan: Surat keterangan sehat dari dokter dan bebas narkoba dari instansi resmi. Usia: Batas usia maksimal 58 tahun. Keahlian: Menguasai teknik pembersihan, penggunaan alat & bahan kimia, serta memahami K3 (Kesehatan & Keselamatan Kerja). Sikap: Disiplin, teliti, bertanggung jawab, etika kerja tinggi, dan mampu bekerja mandiri/tim. 1. Kualifikasi Personel Pendidikan: Minimal SLTA/sederajat. Fisik: Kondisi tubuh prima dan sehat. Sikap & Mental: Waspada, teliti, berintegritas, disiplin, komunikatif, serta mampu menilai situasi. Etika: Menjunjung tinggi 5S (Senyum, Salam, Sapa, Sopan, Santun) dan tidak terlibat hal negatif seperti narkoba atau asusila. 2. Kemampuan Teknis & Tugas Pengaturan & Pengawasan: Mengatur lalu lintas, mengontrol keluar masuk orang/kendaraan. Patroli: Melakukan patroli rutin (stationer dan mobile). Akses Kontrol: Verifikasi identitas, penerbitan kartu tamu, pencatatan buku tamu. Tanggap Darurat: Menyusun dan melaksanakan prosedur darurat, bekerja sama dengan pihak terkait. Pelaporan: Menangani dan melaporkan insiden keamanan. 3. Perlengkapan & Atribut Seragam: Lengkap sesuai peraturan (Perpol), termasuk atribut seperti papan nama, pita, dan sepatu boot. Alat Komunikasi: Radio komunikasi (HT). Alat Bantu: Senter, peluit, borgol, tongkat T, metal detector (opsional). Perlengkapan Tambahan (berbasis risiko): Kamera CCTV, body camera, panic button, sistem proof of patrol (RFID/NFC). 4. Prosedur Kerja & Legalitas Izin Operasional: Memiliki Izin Operasional Badan Usaha Jasa Pengamanan (BUJP) yang sah (KBLI 80100). Kehadiran: Kinerja kehadiran minimal 97-98%. Perjanjian Kerja: Ada perjanjian kerja tertulis yang menjamin hak dan kesejahteraan karyawan. Kepatuhan: Tidak pernah mendapat sanksi (SP3) dari perusahaan penerima kerja', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 383667);
